def _flush_par(self, p: list, buf: list, indent: int) -> None:
    if not buf:
        return
    if buf[0].strip() == "\b":
        p.append((indent or 0, True, "\n".join(buf[1:])))
    else:
        p.append((indent or 1, False, " ".join(buf)))
    buf.clear()
